import assert from 'node:assert/strict';
import fs from 'node:fs';
const {chromium}=await import(process.env.KO_QA_PLAYWRIGHT??'playwright');
const snapshotDir=process.env.KO_QA_ADMIN_SNAPSHOT_DIR;
const cards=JSON.parse(fs.readFileSync(snapshotDir?snapshotDir+'/cards.json':'artifacts/ko-game/src/game/qa/fixtures/cards-2026-10-12-all.json','utf8'));
const resourceCache=process.env.KO_QA_RESOURCE_CACHE;
const resourceReport=resourceCache?JSON.parse(fs.readFileSync(resourceCache+'/report.json','utf8')):null;
const champions=JSON.parse(fs.readFileSync(snapshotDir?snapshotDir+'/champions.json':'artifacts/ko-game/src/game/qa/fixtures/champions-2026-10-12-all.json','utf8'));
const browser=await chromium.launch({...(process.env.KO_QA_CHROME_EXECUTABLE?{executablePath:process.env.KO_QA_CHROME_EXECUTABLE}:{channel:process.env.KO_QA_CHROME_CHANNEL??'chrome'}),headless:true});const results=[],errors=[];let activePage;
try{for(const [width,height] of [[360,740],[375,812],[390,844],[412,915],[1440,900]]){
 const ctx=await browser.newContext({viewport:{width,height},isMobile:width<500,hasTouch:width<500,reducedMotion:'reduce'});const page=await ctx.newPage();activePage=page;page.on('pageerror',e=>errors.push(e.message));await page.route('**/api/**',r=>{const asset=resourceReport?.results.find(a=>a.path===new URL(r.request().url()).pathname);return asset?.cacheFile?r.fulfill({contentType:asset.mime,body:fs.readFileSync(resourceCache+'/'+asset.cacheFile)}):r.fulfill({json:{cards:[],champions:[],frames:[]}});});await page.goto((process.env.KO_QA_ORIGIN??'http://127.0.0.1:5173')+'/qa/champion-features.html');await page.getByTestId('state-json').waitFor({state:'attached'});await page.getByTestId('board-check').evaluate(e=>e.parentElement.style.display='none');await page.evaluate(()=>document.querySelectorAll('style,link[rel=stylesheet]').forEach(e=>e.remove()));for(const file of fs.readdirSync('artifacts/ko-game/dist/public/assets').filter(f=>f.endsWith('.css')&&(f.startsWith('index-')||f.startsWith('game-state-preview-'))))await page.evaluate(css=>{const style=document.createElement('style');style.textContent=css;document.head.append(style);},fs.readFileSync('artifacts/ko-game/dist/public/assets/'+file,'utf8'));
 const state=async()=>JSON.parse(await page.getByTestId('state-json').textContent());const tap=async locator=>{await locator.scrollIntoViewIfNeeded();await page.waitForTimeout(80);const position=await locator.evaluate(e=>e.matches('.ko-board-slot[role=button]')?{x:e.getBoundingClientRect().width/2,y:e.getBoundingClientRect().height*.8}:undefined);if(width<500)await locator.tap(position?{position}:{});else await locator.click(position?{position}:{});};
 const load=async(name,champion=false)=>{await page.evaluate(async({cards,champions,name,champion})=>{
  const {cardRecordToDefinition}=await import('/src/game/cards/published-cards.ts');const {championRecordToDefinition}=await import('/src/game/champions/published-champions.ts');const {createInitialGameState,generateCardInstance}=await import('/src/game/index.ts');const defs=cards.map(cardRecordToDefinition);
  const basic={id:'qa-ally',name:'아군 표적',cardType:'WRESTLER',cost:1,attack:3,health:10,rulesText:'',keywords:[],abilities:[],isToken:false,isChampionToken:false,status:'PUBLISHED'};const enemy={...basic,id:'qa-enemy',name:'상대 표적',attack:1};defs.push(basic,enemy);
  const s=createInitialGameState(undefined,defs);s.minionACardPool=defs;s.status='IN_PROGRESS';s.turn=5;s.activePlayerId=s.players[0].id;
  for(const p of s.players){p.hand=[];p.board=[null,null,null,null];p.champion.quest=null;p.currentGold=30;p.health=20;p.maxHealth=25;p.deck=[generateCardInstance(basic,{instanceId:p.id+'-deck'})];p.graveyard=[];}
  s.players[0].board[2]={...generateCardInstance(basic,{instanceId:'ally'}),boardSlot:2,enteredThisTurn:false};s.players[1].board[0]={...generateCardInstance(enemy,{instanceId:'enemy'}),boardSlot:0,enteredThisTurn:false};
  if(champion){const def=championRecordToDefinition(champions.find(c=>c.name===name));s.players[0].champion={...s.players[0].champion,...def,questProgress:0,questCompleted:false};s.players[0].hand=[generateCardInstance(basic,{instanceId:'hand'})];}
  else s.players[0].hand=[generateCardInstance(defs.find(c=>c.name===name),{instanceId:'played'})];
  window.dispatchEvent(new CustomEvent('ko-qa-load-state',{detail:{state:s,definitions:defs}}));
 },{cards,champions,name,champion});await page.waitForTimeout(150);if(resourceCache)await page.locator('.ko-player-hand img').evaluateAll(async images=>{for(const image of images){await image.decode();if(!image.naturalWidth)throw Error('Card illustration failed to decode');}});};
 const targets=async(preferred)=>{for(let i=0;i<12;i++){const s=await state();const f=s.targetingState;if(!f?.active)return;const id=preferred&&f.validTargetIds.includes(preferred)?preferred:f.validTargetIds.find(id=>!f.selectedTargetIds?.includes(id));assert.ok(id,'target selectable');if(id==='ally')await tap(page.locator('.ko-player-board-row').getByRole('button',{name:'아군 표적',exact:true}));else if(id==='enemy')await tap(page.locator('.ko-opponent-board-row').getByRole('button',{name:'상대 표적',exact:true}));else throw Error('Unexpected target '+id);await page.waitForTimeout(100);}throw Error('target loop');};
 for(const name of ['도적단 모집','봉인','영웅 탄생','파멸 의식','역사상 최강의 주문 카드']){
  console.log('Checking',width,name);await load(name);await tap(page.locator('.ko-player-hand').getByRole('button',{name,exact:true}));await tap(page.getByRole('button',{name:'사용',exact:true}));await targets();const s=await state();assert.equal(s.players[0].hand.some(c=>c.instanceId==='played'),false,name);if(name==='봉인'){const moved=s.players[0].deck.find(c=>c.instanceId==='enemy');assert.ok(moved);assert.deepEqual([moved.currentCost,moved.currentAttack,moved.currentHealth],[1,1,1]);}if(name==='도적단 모집')assert.ok(s.players[0].board[2].keywords.includes('WANTED'));if(name==='파멸 의식')assert.equal(s.players[0].board[2],null);results.push(width+':touch/choice/cast '+name+' PASS');
 }
 if(snapshotDir){
 for(const name of ['아비터','판도라','카스토']){
  await load(name);await tap(page.locator('.ko-player-hand').getByRole('button',{name,exact:true}));await tap(page.getByRole('button',{name:'1구역에 카드 배치',exact:true}));
  if(name==='카스토'){
   await page.evaluate(async()=>{const {executeAction}=await import('/src/game/index.ts');let s=JSON.parse(document.querySelector('[data-testid=state-json]').textContent);for(let i=0;i<2;i++){const r=executeAction(s,{type:'END_TURN',playerId:s.activePlayerId});if(!r.success)throw Error(r.errorCode);s=r.state;}window.dispatchEvent(new CustomEvent('ko-qa-load-state',{detail:{state:s,definitions:s.cardPool}}));});
   const before=await page.locator('.ko-player-board-row').boundingBox();await tap(page.locator('.ko-player-board-row').getByRole('button',{name:'액티브',exact:true}));
   const during=await page.locator('.ko-player-board-row').boundingBox();assert.ok(Math.abs(before.width-during.width)<1,'target selection preserves board width');
   assert.equal(await page.evaluate(()=>visualViewport.scale),1,'target selection does not zoom');
  }
  await targets();const current=await state();const source=current.players[0].board.find(c=>c?.instanceId==='played');assert.ok(source,name+' remains on board');
  if(name==='아비터')assert.equal(current.players[1].board[0].isSilenced,true);
  if(name==='판도라')assert.equal(current.players[1].board[0].currentHealth,9);
  if(name==='카스토')assert.equal(source.currentAttack,cards.find(c=>c.name===name).attack+10);
  results.push(width+':current admin '+name+' actual summon/target/result PASS');
 }
 await load('챔피언 판도라',true);await tap(page.locator('.ko-player-ability'));assert.equal((await state()).targetingState.maxTargets,1);await targets('enemy');assert.equal((await state()).players[1].board[0].currentHealth,9);results.push(width+':current champion Pandora one selected wrestler PASS');
 }
 await load('네브라, 어둠의 천사');await tap(page.locator('.ko-player-hand').getByRole('button',{name:'네브라, 어둠의 천사',exact:true}));await tap(page.getByRole('button',{name:'1구역에 카드 배치',exact:true}));await targets();assert.ok((await state()).players[0].board[2].grantedText);results.push(width+':Nebrah summon and grant through UI PASS');
 await load('챔피언 크루세이더즈',true);await tap(page.locator('.ko-player-ability'));const s=await state();assert.equal(s.players[0].health,22);assert.equal(s.players[0].board[2].currentAttack,4);results.push(width+':Crusaders actual ability touch PASS');assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false);await page.waitForTimeout(1500);await page.screenshot({path:'qa-results/current-content-'+width+'.png'});await ctx.close();
}assert.deepEqual(errors,[]);console.log(JSON.stringify({results,errors},null,2));}catch(error){if(activePage){console.log(await activePage.evaluate(()=>({viewport:[innerWidth,innerHeight],orientation:matchMedia('(orientation: portrait)').matches,styles:[...document.styleSheets].map(s=>({href:s.href,count:s.cssRules.length})),elements:['.ko-game-shell','.ko-game-stage','.ko-game-controls','.ko-player-board-row'].map(selector=>{const e=document.querySelector(selector),s=getComputedStyle(e),r=e.getBoundingClientRect();return {selector,position:s.position,display:s.display,rect:{x:r.x,y:r.y,width:r.width,height:r.height},custom:s.getPropertyValue('--ko-field-width')};})})));await activePage.screenshot({path:'qa-results/current-content-browser-failure.png'});}throw error;}finally{await browser.close();}
